<template><div class="page"><header><div><h2>我的课程</h2><p>仅展示当前教师负责的课程</p></div><button @click="openCreate">创建课程</button></header><section class="stats"><div><span>授课课程</span><strong>{{ courses.length }}</strong></div><div><span>学生人次</span><strong>{{ courses.reduce((n,c)=>n+c.studentCount,0) }}</strong></div><div><span>进行中</span><strong>{{ courses.filter(c=>c.courseStatus===1).length }}</strong></div></section><p v-if="message" class="error">{{ message }}</p><section class="list"><article v-for="c in courses" :key="c.courseId"><div><small>{{ c.courseCode }} · {{ c.semester }}</small><h3>{{ c.courseName }}</h3><p>{{ c.departmentName||'未设置部门' }} · {{ c.studentCount }} 名学生</p></div><span>{{ courseStatusLabel(c.courseStatus) }}</span><div class="actions"><button @click="$emit('navigate',{key:'my-task',name:'实验任务'})">管理任务</button><button @click="$emit('navigate',{key:'my-score',name:'成绩评定'})">成绩评定</button></div></article><div v-if="!loading&&courses.length===0" class="empty">暂无授课课程</div></section><teleport to="body"><div v-if="dialog" class="overlay" @click.self="dialog=false"><section class="modal"><h3>创建课程</h3><div class="grid"><label>课程编码<input v-model.trim="form.courseCode"/></label><label>课程名称<input v-model.trim="form.courseName"/></label><label>学期<input v-model.trim="form.semester"/></label><label>学分<input v-model.number="form.credit" type="number" min="1"/></label><label>总学时<input v-model.number="form.totalHours" type="number" min="1"/></label><label>所属部门<select v-model="form.departmentId"><option value="">暂不设置</option><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.departmentName }}</option></select></label><label class="full">课程描述<textarea v-model.trim="form.description" rows="3"/></label></div><p v-if="formError" class="error">{{ formError }}</p><footer><button @click="dialog=false">取消</button><button class="primary" @click="save">保存</button></footer></section></div></teleport></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{createCourse,courseStatusLabel,getCoursePage,type CourseListItem}from'../../utils/teachingApi';import{getMyProfile}from'../../utils/authApi';import{getDepartmentTree,type DepartmentItem}from'../../utils/personnelApi';defineEmits<{navigate:[payload:{key:string;name:string}]}>();const courses=ref<CourseListItem[]>([]),departments=ref<DepartmentItem[]>([]),loading=ref(false),dialog=ref(false),teacherId=ref(0),message=ref(''),formError=ref('');const form=reactive({courseCode:'',courseName:'',semester:'',credit:1,totalHours:16,departmentId:'' as number|'',description:''});const flat=(x:DepartmentItem[]):DepartmentItem[]=>x.flatMap(i=>[i,...flat(i.children||[])]);const err=(e:unknown)=>e instanceof Error?e.message:'操作失败';async function load(){loading.value=true;try{courses.value=(await getCoursePage({pageNum:1,pageSize:500})).records}catch(e){message.value=err(e)}finally{loading.value=false}}function openCreate(){Object.assign(form,{courseCode:'',courseName:'',semester:'',credit:1,totalHours:16,departmentId:'',description:''});dialog.value=true}async function save(){if(!form.courseCode||!form.courseName||!form.semester||!teacherId.value){formError.value='请完整填写必填信息';return}try{await createCourse({courseCode:form.courseCode,courseName:form.courseName,semester:form.semester,credit:form.credit,totalHours:form.totalHours,teacherId:teacherId.value,departmentId:form.departmentId===''?undefined:form.departmentId,description:form.description||undefined});dialog.value=false;await load()}catch(e){formError.value=err(e)}}onMounted(async()=>{try{const[p,t]=await Promise.all([getMyProfile(),getDepartmentTree()]);teacherId.value=p.personId;departments.value=flat(t)}catch(e){message.value=err(e)}await load()});
</script>
<style scoped>.page{height:100%;overflow:auto;padding:28px 36px;background:transparent;color:#172033}header{display:flex;justify-content:space-between;align-items:center}h2{margin:0}header p{margin:5px 0 0;color:#7b8495}header button,.primary{border:0;border-radius:8px;padding:9px 15px;background:#2563eb;color:#fff}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.stats div,.list article{background:#fff;border:1px solid #e7ebf1;border-radius:12px;padding:16px}.stats span{display:block;color:#7b8495;font-size:12px}.stats strong{font-size:24px}.list{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.list article{display:grid;grid-template-columns:1fr auto;gap:12px}.list h3{margin:6px 0}.list p,.list small{color:#7b8495;font-size:12px}.actions{grid-column:1/-1;display:flex;gap:8px;border-top:1px solid #eef1f5;padding-top:12px}.actions button,.modal footer button{border:0;border-radius:7px;padding:7px 11px;background:#eef1f6}.empty{padding:50px;text-align:center;color:#8992a2}.error{color:#b42336}.overlay{position:fixed;inset:0;z-index:1200;display:flex;align-items:center;justify-content:center;background:#0f172a6b}.modal{width:min(650px,90%);padding:22px;background:#fff;border-radius:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.grid label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:#687386}.grid input,.grid select,.grid textarea{border:1px solid #dfe4ec;border-radius:8px;padding:9px;font:inherit}.full{grid-column:1/-1}.modal footer{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}@media(max-width:750px){.list,.stats,.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
